cd /scr/wurgaft/auto-psych/agent_trees/88c1bd3cf1e5f7a8/repo/_runs/cell_1/experiment3/model_loop/iter_0/candidate_3/scratch; cat > screen2.py << 'EOF'
import sys
import screen as SC
from screen import *
base=cache.setdefault(0.9,lls(0.9)).copy()
contains=np.zeros(len(MEM)); contains[35:45]=1
ends=np.zeros(len(MEM)); ends[25:35]=1
def run(name, mod, nz):
    def f(z):
        SC.cache[0.9]=mod(base,z[6:])
        return nll(pred(tr(z[:6]),0.9))
    z0=np.r_[-0.74,0.005,0.057,-4.76,-4,0.51,np.zeros(nz)]
    r=minimize(f,z0,method="Nelder-Mead",options=dict(maxiter=3000,xatol=1e-4,fatol=1e-4))
    r=minimize(f,r.x,method="Nelder-Mead",options=dict(maxiter=3000,xatol=1e-4,fatol=1e-4))
    print(name, r.fun, r.x.round(3), flush=True)
which=sys.argv[1]
if which=="base": run("base", lambda L,z: L, 0)
if which=="contains": run("contains_w", lambda L,z: L+z[0]*contains[None], 1)
if which=="ends": run("ends_w", lambda L,z: L+z[0]*ends[None], 1)
if which=="ruletemp":
    def m(L,z):
        L=L.copy(); L[:,:NF]*=np.exp(z[0]); return L
    run("ruletemp", m, 1)
if which=="rulesizeprior":
    run("rule_size", lambda L,z: L+z[0]*np.r_[np.log(SIZE[:NR]),np.zeros(len(MEM)-NR)][None], 1)
EOF
for w in base contains ends ruletemp rulesizeprior; do /scr/wurgaft/auto-psych/agent_trees/88c1bd3cf1e5f7a8/venv/bin/python screen2.py $w 2>/dev/null > s2_$w.txt & done; wait; cat s2_*.txt

