cd /scr/wurgaft/auto-psych/agent_trees/88c1bd3cf1e5f7a8/repo/_runs/cell_1/experiment3/model_loop/iter_0/candidate_3/scratch; cat > screen3.py << 'EOF'
import sys
from screen import *
LO=M.INTERVAL_LO; HI=M.INTERVAL_HI
mx=np.array([max(s) for s in uniq])[:,None]; mn=np.array([min(s) for s in uniq])[:,None]
above=np.clip(HI[None]-mx,0,None)/100; below=np.clip(mn-LO[None],0,None)/100
openend=((LO==1)|(HI==100)).astype(float)[None]*np.ones((len(uniq),1))
relw=np.log(M.INTERVAL_WIDTH/((LO+HI)/2))[None]*np.ones((len(uniq),1))
def run(name, ex, nz):
    def f(z): return nll(pred(tr(z[:6]),0.9,ex(z[6:])))
    z0=np.r_[-0.74,0.005,0.057,-4.76,-5,3,np.zeros(nz)]
    r=minimize(f,z0,method="Nelder-Mead",options=dict(maxiter=3000,xatol=1e-4,fatol=1e-4))
    r=minimize(f,r.x,method="Nelder-Mead",options=dict(maxiter=3000,xatol=1e-4,fatol=1e-4))
    print(name, r.fun, r.x.round(3), flush=True)
w=sys.argv[1]
if w=="open": run("open", lambda z: z[0]*openend, 1)
if w=="margin": run("margin", lambda z: z[0]*(above+below), 1)
if w=="relw": run("relw", lambda z: z[0]*relw, 1)
if w=="sqrtroom": run("sqrtroom", lambda z: z[0]*(np.sqrt(above)+np.sqrt(below)), 1)
if w=="minroom": run("minroom", lambda z: z[0]*np.minimum(above,below), 1)
EOF
